    public static IHttpResiliencePipelineBuilder AddRetryResiliencePipeline(this IHttpClientBuilder clientBuilder)
    {
        return clientBuilder.AddResilienceHandler("Retry",
            static builder =>
            {
                // See: https://www.pollydocs.org/strategies/retry.html
                builder.AddRetry(new HttpRetryStrategyOptions
                {
                    // Customize and configure the retry logic.
                    BackoffType = DelayBackoffType.Exponential,
                    MaxRetryAttempts = 6,
                    UseJitter = true,
                    Delay = TimeSpan.FromSeconds(5), // wait 5 seconds and try again by default
                    ShouldHandle = static args =>
                    {
                        // any non-successful status code, go ahead and run again. Maybe this can be improved?
                        return ValueTask.FromResult(!args.Outcome.Result.IsSuccessStatusCode);
                    },
                    DelayGenerator = args =>
                    {
                        // if we have a result, and it has a Retry-After header, use that
                        if (args.Outcome.Result is not null && args.Outcome.Result.Headers.RetryAfter is not null)
                        {
                            var delta = args.Outcome.Result?.Headers?.RetryAfter?.Delta.Value;
                            if (delta != null) // the delta is the amount of time we need to wait
                            {
                                return new ValueTask<TimeSpan?>(delta);
                            }
                        }

                        // Return delay hinted by the retry strategy if we fall through to this point
                        return new ValueTask<TimeSpan?>(default(TimeSpan?));
                    }
                });
            });
    }
```

