For the curious, here is what my custom caching policy looks like. The ICache and ISerializer are my own custom code, not Polly specific.

```cs
    /// <summary>
    /// A custom caching policy that uses an ICache internally
    /// The underlying cache code can inject CacheDuration (TimeSpan) and CacheSize (int) keys
    /// into the Polly context to override the default values.
    /// </summary>
    public class CachePolicy : AsyncPolicy
    {
        private readonly Lazy<ICache> cache;
        private readonly ISerializer serializer;
        private readonly TimeSpan defaultCacheDuration;
        private readonly int defaultCacheSize;

        /// <summary>
        /// Constructor
        /// </summary>
        /// <param name="resolver">Resolver</param>
        /// <param name="serializer">Serializer</param>
        /// <param name="defaultCacheDuration">Default cache duration</param>
        /// <param name="defaultCacheSize">Default cache size</param>
        internal CachePolicy(IResolver resolver, ISerializer? serializer, TimeSpan defaultCacheDuration, int defaultCacheSize)
        {
            // don't ask for the cache now, otherwise the cache dependencies will attempt to resolve, resulting in a circular loop
            this.cache = new Lazy<ICache>(() => resolver.GetRequiredService<ICache>());
            this.serializer = serializer ?? ProtobufLZ4Serializer.Instance;
            this.defaultCacheDuration = defaultCacheDuration;
            this.defaultCacheSize = defaultCacheSize;
        }

        /// <inheritdoc/>
        protected override async Task<TResult> ImplementationAsync<TResult>(Func<Context, CancellationToken, Task<TResult>> action,
            Context context, CancellationToken cancellationToken, bool continueOnCapturedContext)
        {
            return await cache.Value.GetOrCreateAsync<TResult>(context.OperationKey,
                async cancelToken =>
                {
                    TResult taskResult = await action(context, cancellationToken);

                    // allow injecting cache duration and cache size into the context
                    TimeSpan cacheDuration;
                    int cacheSize;
                    if (context.TryGetValue("CacheDuration", out object cacheDurationOverride))
                    {
                        cacheDuration = (TimeSpan)cacheDurationOverride;
                    }
                    else
                    {
                        cacheDuration = defaultCacheDuration;
                    }
                    if (context.TryGetValue("CacheSize", out object cacheSizeOverride))
                    {
                        cacheSize = (int)cacheSizeOverride;
                    }
                    else
                    {
                        cacheSize = defaultCacheSize;
                    }
                    return (taskResult, (cacheDuration, cacheSize));
                },
                serializer,
                cancellationToken).ConfigureAwait(continueOnCapturedContext);
        }
    }
